Here is the commit message:
spi: bcm-qspi: fix SFDP BFPT read by usig mspi read

SFDP read shall use the mspi reads when using the bcm_qspi_exec_mem_op()
call. This fixes SFDP parameter page read failures seen with parts that
now use SFDP protocol to read the basic flash parameter table.

Fixes: 5f195ee7d830 ("spi: bcm-qspi: Implement the spi_mem interface")
Signed-off-by: Kamal Dasu <kamal.dasu@broadcom.com>
Tested-by: Florian Fainelli <florian.fainelli@broadcom.com>
Reviewed-by: Florian Fainelli <florian.fainelli@broadcom.com>
Link: https://msgid.link/r/20240109210033.43249-1-kamal.dasu@broadcom.com
Signed-off-by: Mark Brown <broonie@kernel.org>

Here is the root cause:
The bug was caused by the `bcm_qspi_exec_mem_op` function not correctly handling SFDP (Serial Flash Discoverable Parameters) reads. Specifically, the function did not set the `mspi_read` flag to true for the SFDP read command (`SPINOR_OP_RDSFDP`), which led to failures in reading the basic flash parameter table when using the SFDP protocol.

Here is the patch:
 #include <linux/slab.h>
 #include <linux/spi/spi.h>
-#include <linux/spi/spi-mem.h>
+#include <linux/mtd/spi-nor.h>
 #include <linux/sysfs.h>
 #include <linux/types.h>

 static int bcm_qspi_exec_mem_op(struct spi_mem *mem,
 				const struct spi_mem_op *op)
 {
 	struct spi_device *spi = mem->spi;
 	struct bcm_qspi *qspi = spi_controller_get_devdata(spi->controller);
 	int ret = 0;
 	bool mspi_read = false;
 	u32 addr = 0, len;
 	u_char *buf;

 	if (!op->data.nbytes || !op->addr.nbytes || op->addr.nbytes > 4 ||
 	    op->data.dir != SPI_MEM_DATA_IN)
 		return -EOPNOTSUPP;

 	buf = op->data.buf.in;
 	addr = op->addr.val;
 	len = op->data.nbytes;

 	if (has_bspi(qspi) && bcm_qspi_bspi_ver_three(qspi) == true) {
 		/*
 		 * The address coming into this function is a raw flash offset.
 		 * But for BSPI <= V3, we need to convert it to a remapped BSPI
 		 * address. If it crosses a 4MB boundary, just revert back to
 		 * using MSPI.
 		 */
 		addr = (addr + 0xc00000) & 0xffffff;

 		if ((~ADDR_4MB_MASK & addr) ^
 		    (~ADDR_4MB_MASK & (addr + len - 1)))
 			mspi_read = true;
 	}

 	/* non-aligned and very short transfers are handled by MSPI */
 	if (!IS_ALIGNED((uintptr_t)addr, 4) || !IS_ALIGNED((uintptr_t)buf, 4) ||
-	    len < 4)
+	    len < 4 || op->cmd.opcode == SPINOR_OP_RDSFDP)
 		mspi_read = true;

 	if (!has_bspi(qspi) || mspi_read)
 		return bcm_qspi_mspi_exec_mem_op(spi, op);

 	ret = bcm_qspi_bspi_set_mode(qspi, op, 0);

 	if (!ret)
 		ret = bcm_qspi_bspi_exec_mem_op(spi, op);

 	return ret;
 }



